    public void doSync(Component c)
    {
        // The DATABASE sync, which adds locomotives and deletes and re-adds routes.
        //
        // The state sync next door was guarded because it turns every function off; this one was not,
        // and it is the more invasive of the two. The model defers only the address update - "A rename
        // and a manual address change are both refused while running; a sync had no such guard" - and
        // everything else in it proceeds. Found by review: one door of a pair fixed, which is this
        // codebase's recurring shape.
        if (refuseWhileAutonomyRunning(c)) return;

        javax.swing.SwingUtilities.invokeLater(() -> 
        {
            this.syncMenuItem.setEnabled(false);
            this.functionsMenu.setEnabled(false);
            
            new Thread(() ->
            {
                Integer r = this.syncWithCS2();
                refreshRouteList();
                this.selector.refreshLocSelectorList();
                this.repaintLoc(true, null);
                this.repaintLayout();

                this.syncMenuItem.setEnabled(true);
                this.functionsMenu.setEnabled(true);

                if (c != null)
                {
                    if (r == SYNC_ALREADY_RUNNING)
                    {
                        // Not a failure.  Reporting it as one told the user their sync had failed
                        // when in fact another one was doing the job for them.
                        javax.swing.SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(
                            c,
                            I18n.t("ui.infoSyncAlreadyRunning")
                        ));
                    }
                    else if (r == -1)
                    {
                        javax.swing.SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(
                            c,
                            I18n.t("ui.errorSyncFailedSeeLog")
                        ));
                    }
                    else
                    {
                        javax.swing.SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(
                            c,
                            I18n.f("ui.infoSyncCompleteItemsAdded", r.toString())
                        ));
                    }
                }
            }).start();
        });
    }
    
    /**
     * Puts the current keyboard mappings on the keyboard
     */
    public void copyCurrentPage()
    {
        this.pageToCopy = this.locMappingNumber;
    }
    
    /**
     * Pastes copied mappings to the current page
     */
    public void pasteCopiedPage()
    {
        if (pageCopied() && this.locMappingNumber != this.pageToCopy)
        {
            int dialogResult = JOptionPane.showOptionDialog(
                this,
                I18n.f(
                    "page.ui.confirmReplaceMappings",
                    this.getPageName(this.locMappingNumber, false),
                    this.getPageName(this.pageToCopy, false)
                ),
                I18n.t("page.ui.dialogPasteMappings"),
                JOptionPane.YES_NO_OPTION,
                JOptionPane.PLAIN_MESSAGE,
                null,
                YES_NO_OPTS,
                YES_NO_OPTS[0]
            );
            if (dialogResult == JOptionPane.YES_OPTION)
            {
                this.locMapping.set(this.locMappingNumber - 1, new HashMap<>(this.locMapping.get(this.pageToCopy - 1)));
                this.pageToCopy = null;
                this.repaintMappings();
                
                // We need to repaint the locomotive if a button on this page was active
                if (currentButtonlocMappingNumber == this.locMappingNumber)
                {
                    this.displayCurrentButtonLoc(this.currentButton);
                }
            }
        }
    }
    
