    public void duplicateRoute(String routeName)
    {
        new Thread(()->
        {  
            if (routeName != null)
            {
                Route currentRoute = this.model.getRoute(routeName);

                if (currentRoute != null && currentRoute instanceof Route)
                {
                    String proposedName = currentRoute.getName() + " (" + I18n.t("route.ui.copy") + " %s)";

                    int i = 1;

                    while (this.model.getRoute(String.format(proposedName, i)) != null)
                    {
                        i++;
                    }

                    this.model.newRoute(String.format(proposedName, i), currentRoute.getRoute(), 
                            currentRoute.getS88(), currentRoute.getTriggerType(), false, currentRoute.getConditions()); 

                    // The list first, and again after the sync.
                    //
                    // The copy exists the moment newRoute returns, so this is when the user should
                    // see it - the sync that used to come first is a network round trip to the
                    // Central Station and takes as long as it takes.  Worse, off the event thread it
                    // is a plain call that can throw: a station that is not answering ended this
                    // worker on a stack trace nobody sees, and the refresh below it never ran at
                    // all.  The copy was then in the route database and not on screen until
                    // something else happened to rebuild the table.
                    refreshRouteList();

                    try
                    {
                        // Ensure route changes are synced
                        this.syncWithCS2();
                    }
                    finally
                    {
                        // Whatever the station said, the copy is real and the list has to show it
                        this.repaintLayout();

                        refreshRouteList();
                    }
                }  
            }
        }).start();
    }
        
    private void BulkEnableOrDisable(boolean enable)
    {
        new Thread(()->
        { 
            String searchString = JOptionPane.showInputDialog(
                this,
                I18n.f(
                    "route.ui.promptEnterSearchStringWithS88State",
                    enable ? I18n.t("ui.stateEnabled") : I18n.t("ui.stateDisabled")
                ),
                "*"
            );
            
            // Cancel returns null, which is not the same as an empty search.  !"".equals(null) is
            // true, so the loop ran and getName().contains(null) threw - killing the worker thread on
            // a stack trace nobody sees, and skipping the sync and refresh that follow it.
            if (searchString != null && !"".equals(searchString))
            {
                for (String routeName : this.model.getRouteList())
                {
                    Route r = this.model.getRoute(routeName);

                    if (r.hasS88() || r.isEnabled())
                    {
                        if (r.getName().contains(searchString) || "*".equals(searchString))
                        {
                             this.model.editRoute(r.getName(), r.getName(), r.getRoute(),
                                        r.getS88(), r.getTriggerType(), enable, r.getConditions());
                        }
                    }
                }

                // Ensure route changes are synced
                this.syncWithCS2();
                this.repaintLayout();
                
                refreshRouteList();
            }
        }).start();
    }
    
    public void enableOrDisableRoute(String routeName, boolean enable)
    {  
        new Thread(() -> 
        {
            Route r = this.model.getRoute(routeName);

            if (r.hasS88())
            {
                this.model.editRoute(r.getName(), r.getName(), r.getRoute(), r.getS88(), r.getTriggerType(), enable, 
                        r.getConditions());

                // Ensure route changes are synced
                this.syncWithCS2();
                this.repaintLayout();
                
                refreshRouteList();
            }
            else
            {
                javax.swing.SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(
                    this,
                    I18n.f("route.ui.errorS88RequiredForAutoFire", r.getName())
                ));
            }
        }).start();
    }

